SELECT json_extract(payload,'$.attending_clinician_id') AS clinician_id,COUNT(*) AS encounter_count FROM records WHERE stream='encounters' AND event BETWEEN '2028-01-01' AND '2028-12-31' AND json_extract(payload,'$.type')='primary_care' AND json_extract(payload,'$.attending_clinician_id') IS NOT NULL GROUP BY 1 ORDER BY 1;
